import {clone} from '../document/model.js';import {capabilities,encodeFrames,encodeRealtime} from './codecs.js';import {FrameRenderer} from './render.js';
const $=s=>document.querySelector(s);
export class Exporter{constructor(app){this.a=app;$('#start-export').onclick=()=>app.safe(()=>this.run());$('#cancel-export').onclick=()=>this.controller?.abort();$('#export-size').onchange=()=>app.safe(()=>this.describe());$('#export-dialog').addEventListener('cancel',e=>{if(this.running){e.preventDefault();this.controller.abort();}});$('#export-dialog [data-close]').addEventListener('click',e=>{if(this.running){e.stopPropagation();this.controller.abort();}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&this.running&&this.cap?.kind==='realtime')this.controller.abort();});}
dimensions(){const size=$('#export-size').value;return size==='project'?[this.a.doc.width,this.a.doc.height]:size.split(',').map(Number);}
async describe(){const [w,h]=this.dimensions();this.cap=await capabilities(w,h,this.a.doc.fps,!!this.a.doc.audio&&!this.a.doc.audio.muted);$('#export-capability').textContent=!this.cap?'This browser cannot encode video. Export your project and open it in a current Safari, Chrome or Edge browser.':this.cap.kind==='frames'?`${this.cap.format.toUpperCase()} · exact frame rendering · ${this.a.doc.fps} fps`:`${this.cap.format.toUpperCase()} compatibility export runs in real time. Keep this tab visible; timing can vary on a busy device.`;$('#start-export').disabled=!this.cap;}
async show(){$('#export-dialog').showModal();$('#export-result').innerHTML='';$('#export-settings').hidden=false;$('#export-progress').hidden=true;await this.describe();}
async run(){if(this.running)return;this.running=true;this.controller=new AbortController();$('#export-dialog [data-close]').disabled=true;$('#start-export').disabled=true;try{await this.runReserved();}finally{this.running=false;$('#export-dialog [data-close]').disabled=false;$('#start-export').disabled=false;}}
async runReserved(){this.a.pause();const p=clone(this.a.doc),[w,h]=this.dimensions(),cap=await capabilities(w,h,p.fps,!!p.audio&&!p.audio.muted);if(!cap)throw Error('No supported video encoder found.');this.cap=cap;if(this.controller.signal.aborted)throw new DOMException('Render cancelled','AbortError');this.running=true;$('#export-settings').hidden=true;$('#export-progress').hidden=false;$('#export-result').innerHTML='';$('#export-dialog [data-close]').disabled=true;const progress=(i,total)=>{$('#export-progress progress').value=i/total;$('#export-frames').textContent=`${i} / ${total} frames · ${Math.round(i/total*100)}%`;};try{await document.fonts.ready;await this.a.audio.load();const audio=await this.a.audio.offline(p),renderer=new FrameRenderer(p,w,h),blob=await (cap.kind==='frames'?encodeFrames:encodeRealtime)(renderer,p,cap,audio,this.controller.signal,progress);if(this.url)URL.revokeObjectURL(this.url);this.url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=this.url;link.download=p.name+'.'+cap.format;link.className='primary';link.textContent=`Download ${cap.format.toUpperCase()}`;const video=document.createElement('video');video.src=this.url;video.controls=true;video.playsInline=true;$('#export-result').append(video,link);video.addEventListener('loadedmetadata',()=>{const meta=document.createElement('p');meta.className='subtle';meta.textContent=`${video.videoWidth} × ${video.videoHeight} · ${video.duration.toFixed(3)}s · ${p.fps} fps requested`;$('#export-result').append(meta);},{once:true});$('#export-frames').textContent='Video ready. Preview it here or download it.';$('#cancel-export').hidden=true;}catch(e){this.a.toast(e.name==='AbortError'?'Render cancelled.':e.message);$('#export-settings').hidden=false;$('#export-progress').hidden=true;if(e.name!=='AbortError')throw e;}finally{this.running=false;$('#export-dialog [data-close]').disabled=false;$('#cancel-export').hidden=false;}}
}
